<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { listings, money } from '../data/mock'
import { usePilotStore, viewingSlots } from '../stores/pilot'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import AppSheet from '../components/AppSheet.vue'
const route=useRoute(),router=useRouter(),store=usePilotStore()
const home=computed(()=>listings.find(h=>h.id === route.params.id))
const imageOpen=ref(false),appointmentOpen=ref(false),contactOpen=ref(false),costsOpen=ref(false),zoomed=ref(false)
const payMonths=ref(3),slot=ref(viewingSlots[0]!),question=ref('这套房子看房时，需要重点检查哪些地方？')
const localDate=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const dates=Array.from({length:5},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return {value:localDate(d),label:i === 0 ? '今天' : i === 1 ? '明天' : ['周日','周一','周二','周三','周四','周五','周六'][d.getDay()],day:`${d.getMonth()+1}/${d.getDate()}`}})
const date=ref(dates[1]!.value)
const viewing=computed(()=>store.viewings.find(v=>v.listingId === home.value?.id))
watch(appointmentOpen,open=>{if(open && viewing.value){date.value=viewing.value.date;slot.value=viewing.value.slot}})
watch(()=>route.params.id,()=>{imageOpen.value=false;appointmentOpen.value=false;contactOpen.value=false;costsOpen.value=false;zoomed.value=false})
function toggleSaved(){if(home.value)store.toggleSaved(home.value.id)}
function confirmAppointment(){if(!home.value || !store.scheduleViewing(home.value.id,date.value,slot.value)) return;appointmentOpen.value=false;store.notify('已保存本地看房计划，未提交任何真实看房预约')}
function ask(){if(!home.value)return;store.sendMessage(`我想了解${home.value.name}，${question.value}`);contactOpen.value=false;router.push('/chat')}
const amenities=[{icon:'wifi',name:'Wi-Fi'},{icon:'refrigerator',name:'冰箱'},{icon:'washing-machine',name:'洗衣机'},{icon:'air-vent',name:'空调'},{icon:'sun',name:'阳台'},{icon:'flame',name:'可做饭'},{icon:'bed',name:'独立卧室'},{icon:'lock',name:'门禁'}]
const similar=computed(()=>listings.filter(h=>h.id !== home.value?.id).slice(0,2))
</script>

<template>
  <AppHeader title="房源详情" back><button v-if="home" class="icon-button" :aria-label="store.savedListings.includes(home.id) ? '取消收藏房源' : '收藏房源'" :aria-pressed="store.savedListings.includes(home.id)" @click="toggleSaved"><AppIcon name="heart" :fill="store.savedListings.includes(home.id) ? 'currentColor' : 'none'" /></button></AppHeader>
  <main v-if="home" class="page listing-page stack">
    <button class="listing-hero" aria-label="放大房源设计示意图" aria-haspopup="dialog" @click="imageOpen=true"><img :src="home.image" :alt="`${home.name}室内示意`" /><span class="photo-kind">模拟房源</span><span class="photo-count"><AppIcon name="image" :size="13" />1 / 1</span></button>
    <section class="listing-summary"><div class="between"><p class="listing-price">{{ money(home.price) }}<small>/月</small></p><button class="payment-link" aria-label="查看租住费用试算" @click="costsOpen=true">费用试算<AppIcon name="chevron-right" :size="14" /></button></div><h1>{{ home.name }}</h1><p class="small muted">{{ home.district }} · {{ home.metro }}</p><div class="listing-specs"><div><strong>{{ home.area }}<small>㎡</small></strong><span>建筑面积</span></div><div><strong>1 室 1 厅</strong><span>整租一居</span></div><div><strong>{{ home.commute }}<small>分钟</small></strong><span>示例通勤</span></div></div><div class="tags"><span v-for="tag in home.tags" :key="tag">{{ tag }}</span></div></section>
    <section class="listing-section"><div class="between"><h2>舒服生活，基本配齐</h2><span class="tiny muted">示例配置</span></div><div class="amenities"><div v-for="item in amenities" :key="item.name"><AppIcon :name="item.icon" :size="23" /><span>{{ item.name }}</span></div></div></section>
    <section class="listing-section"><div class="between"><h2>每天的生活半径</h2><RouterLink :to="{path:'/map',query:{district:home.district}}" class="text-action muted">看地图<AppIcon name="arrow-right" :size="15" /></RouterLink></div><RouterLink :to="{path:'/map',query:{district:home.district}}" class="commute-route"><div class="route-stops"><span><i class="start-stop"></i>{{ home.district }}的家</span><span class="route-line"></span><span><i class="end-stop"></i>张江工作地</span></div><div class="between"><strong>{{ home.commute }}<small>分钟 / 单程</small></strong><span class="tiny muted">{{ home.commute <= 18 ? '步行 / 骑行' : '地铁通勤' }} · 路线示意</span></div></RouterLink><p class="tiny muted address-copy"><AppIcon name="map-pin" :size="13" />{{ home.address }}</p></section>
    <section class="listing-section checks"><h2>带着这些问题去看房</h2><details><summary>房况与居住体验<AppIcon name="chevron-down" :size="17" /></summary><p>留意窗户密封、临街噪音和采光，试用热水、空调及门锁，拍照记录交房状态。</p></details><details><summary>合同与额外费用<AppIcon name="chevron-down" :size="17" /></summary><p>核实房东身份、押付周期、物业服务费、维修责任和退租条件，再决定是否签约。</p></details></section>
    <section class="listing-section similar-homes"><div class="between"><h2>也许你还会喜欢</h2><RouterLink to="/map" class="text-action muted">更多<AppIcon name="chevron-right" :size="14" /></RouterLink></div><div class="similar-grid"><RouterLink v-for="item in similar" :key="item.id" :to="`/listing/${item.id}`"><img :src="item.image" :alt="`${item.district}模拟房源示意`" /><h3>{{ item.district }} · {{ item.area }}㎡</h3><p>{{ money(item.price) }}<small>/月</small></p></RouterLink></div></section>
  </main>
  <div v-if="home" class="listing-actions"><div class="footer-price"><strong>{{ money(home.price) }}</strong><small>/月</small></div><button class="icon-button contact-button" aria-label="咨询演示" aria-haspopup="dialog" @click="contactOpen=true"><AppIcon name="message" /></button><button class="primary" aria-label="预约线下看房（演示）" aria-haspopup="dialog" @click="appointmentOpen=true"><AppIcon :name="viewing ? 'check' : 'calendar'" :size="17" />{{ viewing ? '修改看房计划' : '安排看房' }}</button></div>
  <main v-else class="page empty-fallback"><h1>没有找到这个房源</h1><p class="muted">返回找房页，看看其他选择。</p><RouterLink to="/map" class="primary">返回地图找房</RouterLink></main>
  <AppSheet v-model="imageOpen" title="房源设计示意图" description="1 / 1 · 室内设计示意"><div v-if="home" class="expanded-image" :class="{zoomed}"><img :src="home.image" :alt="`${home.name}室内示意`" /></div><template #footer><button class="secondary" :aria-pressed="zoomed" @click="zoomed=!zoomed">{{ zoomed ? '恢复图片大小' : '放大查看细节' }}</button></template></AppSheet>
  <AppSheet v-model="costsOpen" title="租住费用试算"><div v-if="home" class="stack"><div class="choice-chips"><button v-for="months in [1,3]" :key="months" :aria-pressed="payMonths === months" @click="payMonths=months">押一付{{ months === 1 ? '一' : '三' }}</button></div><dl class="ledger"><div><dt>首期租金 · {{ payMonths }} 个月</dt><dd>{{ money(home.price*payMonths) }}</dd></div><div><dt>押金 · 1 个月</dt><dd>{{ money(home.price) }}</dd></div><div class="total"><dt>首次需准备</dt><dd>{{ money(home.price*(payMonths+1)) }}</dd></div></dl><p class="tiny muted">仅按示例月租计算，押付方式可自行假设。未包含水电、物业等未知费用；实际以核验后的合同为准。</p></div></AppSheet>
  <AppSheet v-model="appointmentOpen" title="预约看房演示" description="仅保存到本机，不会提交真实预约。"><div v-if="home" class="stack"><div class="booking-home"><img :src="home.image" alt="房源示意" /><span><strong>{{ home.name }}</strong><small class="muted">{{ money(home.price) }}/月</small></span></div><div class="date-chips"><button v-for="day in dates" :key="day.value" :class="{active:date === day.value}" :aria-pressed="date === day.value" @click="date=day.value"><span>{{ day.label }}</span><strong>{{ day.day }}</strong></button></div><label class="form-field">其他日期<input v-model="date" type="date" aria-label="计划看房日期" :min="dates[0]!.value" /></label><div class="form-field"><span>方便的时段</span><div class="choice-chips"><button v-for="time in viewingSlots" :key="time" :aria-pressed="slot === time" @click="slot=time">{{ time }}</button></div></div></div><template #footer><button class="primary" :disabled="!date || date < dates[0]!.value" @click="confirmAppointment">保存看房计划<AppIcon name="check" /></button></template></AppSheet>
  <AppSheet v-model="contactOpen" title="咨询服务演示" description="尚未接入真实经纪人。可以先把看房问题整理到找房对话。"><div class="stack"><div class="choice-chips"><button v-for="item in ['需要检查哪些额外费用？','怎样判断采光与隔音？','这套房适合我的通勤吗？']" :key="item" :aria-pressed="question === item" @click="question=item">{{ item }}</button></div><label class="form-field">想了解的问题<input v-model="question" aria-label="想了解的问题" maxlength="200" /></label></div><template #footer><button class="primary" :disabled="!question.trim()" @click="ask">带着问题去聊聊<AppIcon name="arrow-right" /></button></template></AppSheet>
</template>

<style scoped>
.listing-page{padding-top:8px;padding-bottom:calc(120px + var(--safe-bottom));gap:28px}.listing-hero{position:relative;padding:0;width:100%;height:260px;border-radius:20px;overflow:hidden}.listing-hero img{width:100%;height:100%}.photo-kind,.photo-count{position:absolute;bottom:14px;background:#fff;padding:5px 8px;border-radius:6px;font-size:12px}.photo-kind{left:14px}.photo-count{right:14px;display:flex;align-items:center;gap:5px}.listing-price{font-size:32px;font-weight:600;letter-spacing:-.045em;line-height:1.4}.listing-price small{font-size:12px;color:var(--muted);font-weight:400;letter-spacing:0;margin-left:6px}.payment-link{display:flex;align-items:center;gap:4px;font-size:12px;min-height:44px;color:var(--muted);padding:8px 0}.listing-summary h1{font-size:22px;margin:12px 0 8px;line-height:1.6;letter-spacing:-.025em}.listing-specs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:24px 0}.listing-specs>div{display:flex;flex-direction:column;gap:8px}.listing-specs>div+div{border-left:1px solid var(--line);padding-left:18px}.listing-specs strong{font-size:19px;font-weight:500}.listing-specs strong small{font-size:12px;margin-left:3px}.listing-specs span{font-size:12px;color:var(--muted)}.listing-section{border-top:1px solid var(--line);padding-top:24px}.listing-section h2{font-size:18px}.amenities{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px 12px;margin-top:24px}.amenities>div{display:flex;flex-direction:column;align-items:center;gap:12px}.amenities span{font-size:12px;color:#555}.commute-route{display:block;border-radius:18px;background:var(--surface);padding:20px;margin-top:16px}.route-stops{display:flex;align-items:center;gap:10px;font-size:12px}.route-stops>span{display:flex;align-items:center;gap:6px;white-space:nowrap}.route-stops i{width:7px;height:7px;display:inline-block;border-radius:50%;background:var(--ink);flex-shrink:0}.route-stops .end-stop{background:transparent;border:1.5px solid var(--ink)}.route-line{height:1px;background:#bbb;flex:1;min-width:8px}.commute-route>.between{margin-top:22px;align-items:baseline}.commute-route strong{font-size:29px;font-weight:500}.commute-route small{font-size:12px;color:var(--muted);font-weight:400;margin-left:6px}.address-copy{display:flex;align-items:center;gap:6px;margin-top:12px}.checks details{border-bottom:1px solid var(--line)}.checks details:first-of-type{margin-top:12px}.checks summary{display:flex;align-items:center;justify-content:space-between;min-height:54px;list-style:none;cursor:pointer;font-size:13px}.checks summary::-webkit-details-marker{display:none}.checks details>p{font-size:13px;color:var(--muted);padding:0 0 16px}.similar-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:12px}.similar-grid img{height:124px;width:100%;border-radius:14px}.similar-grid h3{font-size:13px;font-weight:500;margin-top:12px}.similar-grid p{font-size:19px;margin-top:5px;font-weight:600}.similar-grid small{font-size:12px;color:var(--muted);font-weight:400;margin-left:4px}.listing-actions{position:fixed;z-index:50;bottom:0;left:50%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;width:min(100%,640px);padding:14px var(--gutter) calc(14px + var(--safe-bottom));background:#fff;border-top:1px solid var(--line)}.footer-price{flex:1;min-width:0;white-space:nowrap}.footer-price strong{font-size:21px;font-weight:600;letter-spacing:-.04em}.footer-price small{color:var(--muted);font-size:12px;margin-left:3px}.listing-actions .primary{flex:1.4;min-width:0;white-space:nowrap}.contact-button{background:var(--surface)}.expanded-image{overflow:auto;border-radius:16px;max-height:55dvh}.expanded-image img{width:100%;height:auto;object-fit:contain}.expanded-image.zoomed img{width:180%;max-width:none}.booking-home{display:flex;gap:14px;align-items:center}.booking-home img{width:64px;height:72px;border-radius:12px}.booking-home span{min-width:0}.booking-home strong{font-size:14px;font-weight:500;line-height:1.7}.booking-home small{display:block;margin-top:8px}.date-chips{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.date-chips button{background:var(--surface);border-radius:12px;padding:12px 4px;min-height:66px;font-size:12px;display:flex;flex-direction:column;gap:8px;align-items:center}.date-chips strong{font-size:14px;font-weight:500}.date-chips .active{background:var(--ink);color:#fff}
@media(max-width:359px){.listing-hero{height:225px}.listing-summary h1{font-size:20px}.listing-specs strong{font-size:17px}.listing-specs>div+div{padding-left:12px}.listing-actions{gap:8px}.listing-actions .primary{font-size:12px;padding-inline:10px}.footer-price strong{font-size:18px}.footer-price small{display:block}.commute-route{padding:16px}.route-stops{font-size:12px;gap:6px}.commute-route>.between{gap:6px}.commute-route small{font-size:12px}.similar-grid{gap:12px}}
</style>